def _probe_anthropic() -> LaneHealth:
    """Claude Code CLI availability.

    All Anthropic calls in this fleet go through the headless ``claude`` CLI
    (Claude Code), not the raw API. Probes for the binary's presence and
    responsiveness to ``--version``. Does not invoke a live prompt.
    """
    import shutil
    import subprocess

    claude_bin = shutil.which("claude")
    if claude_bin is None:
        return LaneHealth(
            lane="claude",
            endpoint="cli:claude",
            status=LaneStatus.DOWN,
            detail="claude CLI not on PATH",
        )
    try:
        start = time.perf_counter()
        result = subprocess.run(
            [claude_bin, "--version"], capture_output=True, timeout=3, text=True
        )
        latency_ms = (time.perf_counter() - start) * 1000
        if result.returncode == 0:
            version = result.stdout.strip() or result.stderr.strip()
            return LaneHealth(
                lane="claude",
                endpoint=f"cli:{claude_bin}",
                status=LaneStatus.UP,
                latency_ms=latency_ms,
                detail=version,
            )
        return LaneHealth(
            lane="claude",
            endpoint=f"cli:{claude_bin}",
            status=LaneStatus.DEGRADED,
            latency_ms=latency_ms,
            detail=f"exit {result.returncode}",
        )
    except (subprocess.TimeoutExpired, OSError) as exc:
        return LaneHealth(
            lane="claude",
            endpoint=f"cli:{claude_bin}",
            status=LaneStatus.DEGRADED,
            detail=str(exc),
        )

