def _probe_cli(binary: str, lane_name: str) -> LaneHealth:
    """Probe a headless CLI tool (``claude`` or ``gemini``) via ``--version``.

    Both CLIs in this fleet use the same shape: present on PATH, responds to
    ``--version`` within a couple seconds, exit 0 = healthy. No live prompt
    invocation (which would cost tokens).
    """
    import shutil
    import subprocess

    resolved = shutil.which(binary)
    if resolved is None:
        return LaneHealth(
            lane=lane_name,
            endpoint=f"cli:{binary}",
            status=LaneStatus.DOWN,
            detail=f"{binary} CLI not on PATH",
        )
    try:
        start = time.perf_counter()
        result = subprocess.run(
            [resolved, "--version"], capture_output=True, timeout=3, text=True
        )
        latency_ms = (time.perf_counter() - start) * 1000
        if result.returncode == 0:
            version = result.stdout.strip() or result.stderr.strip()
